45:        {
46:            error = null;
47:            return _poSSwitcher.IsPostMerge(header)
48:                ? ValidateTheMergeChecks(header) && base.Validate(header, parent, isUncle, out error)
49:                : ValidatePoWTotalDifficulty(header) && _preMergeHeaderValidator.Validate(header, parent, isUncle, out error);
50:        }
52:        protected override bool ValidateTotalDifficulty(BlockHeader parent, BlockHeader header, ref string? error) =>
53:            _poSSwitcher.IsPostMerge(header) || base.ValidateTotalDifficulty(parent, header, ref error);
55:        private bool ValidatePoWTotalDifficulty(BlockHeader header)
56:        {
57:            if (header.Difficulty == 0)
58:            {
59:                if (_logger.IsWarn) _logger.Warn($"Invalid block header {header.ToString(BlockHeader.Format.Short)} - zero difficulty for PoW block.");
60:                return false;
61:            }
63:            return true;
64:        }
66:        private bool ValidateTheMergeChecks(BlockHeader header)
67:        {
68:            (bool IsTerminal, bool IsPostMerge) = _poSSwitcher.GetBlockConsensusInfo(header);
69:            bool terminalTotalDifficultyChecks = ValidateTerminalTotalDifficultyChecks(header, IsTerminal);
70:            bool valid = !IsPostMerge ||
71:                        ValidateHeaderField(header, header.Difficulty, UInt256.Zero, nameof(header.Difficulty))
72:                        && ValidateHeaderField(header, header.Nonce, 0u, nameof(header.Nonce))
73:                        && ValidateHeaderField(header, header.UnclesHash, Keccak.OfAnEmptySequenceRlp, nameof(header.UnclesHash));
75:            return terminalTotalDifficultyChecks && valid;
76:        }
78:        protected override bool ValidateExtraData(BlockHeader header, BlockHeader? parent, IReleaseSpec spec, bool isUncle, ref string? error)
79:        {
80:            if (_poSSwitcher.IsPostMerge(header))
81:            {
82:                if (header.ExtraData.Length > MaxExtraDataBytes)
