84:                    if (_logger.IsWarn) _logger.Warn($"Invalid block header {header.ToString(BlockHeader.Format.Short)} - the {nameof(header.ExtraData)} exceeded max length of {MaxExtraDataBytes}.");
85:                    error = BlockErrorMessages.InvalidExtraData;
86:                    return false;
87:                }
89:                return true;
90:            }
92:            return base.ValidateExtraData(header, parent, spec, isUncle, ref error);
