    38→        public unsafe static void BytesToNibbleBytes(ReadOnlySpan<byte> bytes, Span<byte> nibbles)
    39→        {
    40→            // Ensure the length of the nibbles span is exactly twice the length of the bytes span.
    41→            if (nibbles.Length != 2 * bytes.Length)
    42→            {
    43→                ThrowArgumentException();
    44→            }
    45→
    46→            int processed = 0;
    47→            if (Vector256.IsHardwareAccelerated)
    48→            {
    49→                int len256 = (bytes.Length - processed) / Vector256<byte>.Count;
    50→                if (len256 > 0)
    51→                {
    52→                    ReadOnlySpan<Vector256<byte>> input = MemoryMarshal.CreateReadOnlySpan(ref Unsafe.As<byte, Vector256<byte>>(ref MemoryMarshal.GetReference(bytes)), len256);
    53→                    len256 *= Vector256<byte>.Count;
    54→
    55→                    ref Vector256<ushort> output = ref Unsafe.As<byte, Vector256<ushort>>(
    56→                        ref Unsafe.Add(ref MemoryMarshal.GetReference(nibbles), processed * 2));
    57→
    58→                    for (int i = 0; i < input.Length; i++)
    59→                    {
    60→                        // Get the bytes where each byte contains 2 nibbles that we want to move into their own byte.
    61→                        Vector256<byte> value = input[i];
    62→
    63→                        // Mask off lower nibble 0x0f and split each byte into two bytes and store them in two separate vectors.
